import { useState } from 'react'
import { Button } from 'moru-ui'
import { ButtonGroup, ButtonGroupText } from 'moru-ui'

export function PageActions() {
  const [page, setPage] = useState(1)
  return (
    <ButtonGroup aria-label="Page navigation">
      <Button
        type="button"
        variant="secondary"
        disabled={page === 1}
        onClick={() => setPage((value) => Math.max(1, value - 1))}
      >
        Previous
      </Button>
      <ButtonGroupText aria-live="polite">{page} / 5</ButtonGroupText>
      <Button
        type="button"
        variant="secondary"
        disabled={page === 5}
        onClick={() => setPage((value) => Math.min(5, value + 1))}
      >
        Next
      </Button>
    </ButtonGroup>
  )
}

